{"command": "echo 'def get_document(user_id: str, document_id: str, repository, cache, shared=False):
    if shared:
        # Use shared (application-wide) cache
        cache_key = f"{user_id}:{document_id}"
        if cache_key not in cache:
            cache[cache_key] = repository.read(user_id, document_id)
        return cache[cache_key]
    else:
        # Use local (request-scoped) cache
        if document_id not in cache:
            cache[document_id] = repository.read(user_id, document_id)
        return cache[document_id]' > ./app/service.py"}

